use bevy::prelude::*;
use serde_json::{Value,json};
fn main(){let input:Value=serde_json::from_str(&std::fs::read_to_string("docs/audit/bf144/442/runtime-baseline/parameters.json").unwrap()).unwrap();let mut rows=Vec::new();for row in input["rows"].as_array().unwrap(){let raw=row["view_yaw"].as_f64().unwrap()as f32;let player=row["player_view_yaw"].as_f64().map(|v|v as f32);let selected=player.unwrap_or(raw);let command=Vec2::new(row["input_move"][0].as_f64().unwrap()as f32,row["input_move"][1].as_f64().unwrap()as f32);let expected=bevy_als::als::motion::view_relative_move_direction(command,selected)*command.length().min(1.);rows.push(json!({"ordinal":row["ordinal"],"computed":expected.to_array(),"actual":row["desired_motion"],"selected_yaw":selected}));}std::fs::write(std::env::args().nth(1).unwrap(),json!(rows).to_string()).unwrap();println!("Replayed240 actual input directions through the unchanged public direction helper");}
